"use client";

import Link from "next/link";
import { useEffect, useMemo, useRef, useState, type DragEvent, type ReactNode } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { useLocale } from "@/components/locale-provider";
import { WorkflowHelp } from "@/components/workflow-help";
import { createWorkflow, getWorkflow, updateWorkflow, listWorkflowParticipants, listWorkflowParticipantOptions, listWorkflowVersions, listWorkflowTemplates, listWorkflowDynamicValues, listWorkflowFunctions, type Workflow, type WorkflowParticipant, type WorkflowDataTemplate, type WorkflowFunction } from "@/lib/api/workflows";

type Action = { type: string; config: Record<string, unknown> };
type ConditionRule = { field: string; operator: string; value: string };
type ConditionGroup = { logic: "AND" | "OR"; rules: Array<ConditionRule | ConditionGroup> };
type ParticipantOption = { id: string; name?: string | null; email?: string | null };
type GroupOption = { id: string; name: string; memberCount?: number };
type WorkflowField = { id: string; name: string; description: string; type: string; required: boolean; defaultValue?: string; max?: number; options?: string[] };
type StateDraft = { name: string; description: string; terminal: boolean };
type TransitionDraft = { from: number; to: number; name: string; description: string; trigger: string; condition: unknown; execution: "AUTOMATIC" | "MANUAL"; before: Action[]; during: Action[]; after: Action[] };
type Position = { x: number; y: number };
type Phase = "before" | "during" | "after";

const BLUE = "#1B66EA";
const GREEN = "#0B8F55";
const FIELD_TYPES = [
  ["single", "Single line text", "نص بسطر واحد", "▭"], ["multi", "Multi line text", "نص متعدد الأسطر", "▤"], ["number", "Number", "رقم", "123"],
  ["datetime", "Date & time", "التاريخ والوقت", "◷"], ["date", "Date", "التاريخ", "□"], ["boolean", "Yes/No", "نعم / لا", "◉"],
  ["choice", "Choice", "اختيار", "▾"], ["email", "Email", "البريد الإلكتروني", "@"],
] as const;
const TRIGGERS = [
  ["upload", "File uploaded", "تم رفع ملف"], ["create", "File/folder created", "تم إنشاء ملف/مجلد"], ["move", "File/folder moved", "تم نقل ملف/مجلد"],
  ["copy", "File/folder copied", "تم نسخ ملف/مجلد"], ["rename", "File renamed", "تمت إعادة تسمية الملف"], ["delete", "File moved to trash", "تم نقل الملف إلى السلة"],
  ["properties_updated", "Properties updated", "تم تحديث الخصائص"], ["ready", "File marked as ready", "تم تعليم الملف كجاهز"],
] as const;
const ACTIONS = [
  ["notify", "System notification", "إشعار للنظام"], ["move", "Move", "نقل"], ["copy", "Copy", "نسخ"], ["generate_link", "Generate link", "إنشاء رابط"],
  ["share", "Share", "مشاركة"], ["request_approval", "Request approval", "طلب موافقة"], ["data_template", "Data template", "قالب بيانات"], ["custom_function", "Custom function", "دالة مخصصة"], ["favorite", "Add to favorites", "إضافة للمفضلة"],
  ["tag", "Add tag", "إضافة وسم"], ["mark_final", "Mark as final", "تعليم كنهائي"], ["create_folder", "Create folder", "إنشاء مجلد"],
] as const;
const DEFAULT_POSITIONS: Position[] = [{ x: 90, y: 100 }, { x: 450, y: 100 }, { x: 810, y: 100 }, { x: 450, y: 360 }, { x: 810, y: 360 }, { x: 1170, y: 360 }];

function txt(ar: boolean, en: string, arText: string) { return ar ? arText : en; }
function action(type: string, config: Record<string, unknown> = {}): Action { return { type, config }; }
function transitionDefaults(from: number, to: number, n: number): TransitionDraft { return { from, to, name: n === 1 ? "Complete" : `Transition ${n}`, description: "", trigger: "", condition: "any", execution: "AUTOMATIC", before: [], during: [], after: [] }; }
function normalizePhaseActions(raw: unknown) {
  if (Array.isArray(raw)) return { before: [], during: raw as Action[], after: [] };
  const obj = (raw && typeof raw === "object" ? raw : {}) as Record<string, unknown>;
  const clean = (v: unknown) => Array.isArray(v) ? v.map((x) => ({ type: String((x as Record<string, unknown>)?.type ?? "notify"), config: ((x as Record<string, unknown>)?.config && typeof (x as Record<string, unknown>).config === "object" ? (x as Record<string, unknown>).config : {}) as Record<string, unknown> })) : [];
  return { before: clean(obj.before), during: clean(obj.during), after: clean(obj.after) };
}

function FieldEditor({ draft, ar, onChange, onCancel, onSave }: { draft: WorkflowField; ar: boolean; onChange: (next: WorkflowField) => void; onCancel: () => void; onSave: () => void }) {
  const ft = FIELD_TYPES.find((x) => x[0] === draft.type);
  const set = (key: keyof WorkflowField, value: unknown) => onChange({ ...draft, [key]: value });
  return <div className="fixed inset-0 z-[230] flex items-center justify-center bg-slate-950/40 p-4 backdrop-blur-[2px]">
    <div className="w-[min(620px,95vw)] overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-2xl animate-[fadeIn_.18s_ease-out]" dir={ar ? "rtl" : "ltr"}>
      <div className="border-b border-slate-100 px-6 py-5"><div className="text-[10px] font-semibold uppercase tracking-[.15em] text-[#1B66EA]">{txt(ar,"Workflow field","حقل سير العمل")}</div><h2 className="mt-1 text-[18px] font-semibold text-slate-900">{txt(ar,"Configure custom field","إعداد الحقل المخصص")}</h2><p className="mt-1 text-[11px] text-slate-500">{txt(ar,`Field type: ${ft?.[1] ?? draft.type}`,`نوع الحقل: ${ft?.[2] ?? draft.type}`)}</p></div>
      <div className="grid gap-4 p-6 sm:grid-cols-2">
        <label className="block text-[11px] font-medium text-slate-700 sm:col-span-2">{txt(ar,"Field name","اسم الحقل")}<input autoFocus value={draft.name} onChange={(e) => set("name", e.target.value)} placeholder={txt(ar,"Enter field name","أدخل اسم الحقل")} className="mt-1.5 w-full rounded-xl border border-slate-200 px-3 py-2.5 text-[12px] outline-none transition focus:border-[#1B66EA] focus:ring-2 focus:ring-[#1B66EA]/10" /></label>
        <label className="block text-[11px] font-medium text-slate-700 sm:col-span-2">{txt(ar,"Description","الوصف")}<textarea value={draft.description} onChange={(e) => set("description", e.target.value)} placeholder={txt(ar,"Add field description","أضف وصفاً للحقل")} rows={3} className="mt-1.5 w-full resize-none rounded-xl border border-slate-200 px-3 py-2.5 text-[12px] outline-none transition focus:border-[#1B66EA]" /></label>
        {["single", "multi"].includes(draft.type) && <label className="block text-[11px] font-medium text-slate-700">{txt(ar,"Maximum characters","الحد الأقصى للأحرف")}<input type="number" min={1} value={draft.max ?? ""} onChange={(e) => set("max", e.target.value ? Number(e.target.value) : undefined)} className="mt-1.5 w-full rounded-xl border border-slate-200 px-3 py-2.5 text-[12px]" /></label>}
        {draft.type === "choice" && <label className="block text-[11px] font-medium text-slate-700 sm:col-span-2">{txt(ar,"Choices","الخيارات")}<input value={(draft.options ?? []).join(", ")} onChange={(e) => set("options", e.target.value.split(",").map((x) => x.trim()).filter(Boolean))} placeholder={txt(ar,"Approved, Rejected, Needs changes","موافق، مرفوض، يحتاج تعديلات")} className="mt-1.5 w-full rounded-xl border border-slate-200 px-3 py-2.5 text-[12px]" /></label>}
        <label className="block text-[11px] font-medium text-slate-700">{txt(ar,"Default value","القيمة الافتراضية")}<input value={draft.defaultValue ?? ""} onChange={(e) => set("defaultValue", e.target.value)} className="mt-1.5 w-full rounded-xl border border-slate-200 px-3 py-2.5 text-[12px]" /></label>
        <label className="flex items-center gap-2 self-end pb-2 text-[11px] font-medium text-slate-700"><input type="checkbox" checked={draft.required} onChange={(e) => set("required", e.target.checked)} className="h-4 w-4 accent-[#1B66EA]" />{txt(ar,"Make this field mandatory","اجعل هذا الحقل إلزامياً")}</label>
      </div>
      <div className="flex justify-end gap-2 border-t border-slate-100 px-6 py-4"><button type="button" onClick={onCancel} className="rounded-xl border border-slate-200 px-4 py-2 text-[11px] font-medium text-slate-600 hover:bg-slate-50">{txt(ar,"Cancel","إلغاء")}</button><button type="button" disabled={!draft.name.trim()} onClick={onSave} className="rounded-xl bg-[#0B8F55] px-5 py-2 text-[11px] font-semibold text-white shadow-sm disabled:opacity-40">{txt(ar,"Create field","إنشاء الحقل")}</button></div>
    </div>
  </div>;
}

function DynamicValueButtons({ ar, onInsert, values }: { ar: boolean; onInsert: (value: string) => void; values?: Array<{ path: string; label: string }> }) {
  const fallback = [["file.name", ar ? "اسم الملف" : "File name"], ["file.id", ar ? "معرّف الملف" : "File ID"], ["file.extension", ar ? "الامتداد" : "Extension"], ["file.folderId", ar ? "معرّف المجلد" : "Folder ID"]];
  const items = values?.length ? values.slice(0, 12).map((v) => [v.path, v.label]) : fallback;
  return <div className="mt-1.5 flex flex-wrap gap-1">{items.map(([path, label]) => <button key={path} type="button" title={`{{${path}}}`} onClick={() => onInsert(`{{${path}}}`)} className="rounded-md border border-slate-200 bg-slate-50 px-1.5 py-1 text-[8.5px] text-slate-500 hover:border-[#1B66EA] hover:bg-[#F8FBFF] hover:text-[#1B66EA]">{label}</button>)}</div>;
}

function ActionEditor({ actions, onChange, resourceType, ar, participants, groups, templates = [], functions = [] }: { actions: Action[]; onChange: (next: Action[]) => void; resourceType: string; ar: boolean; participants: WorkflowParticipant[]; groups: GroupOption[]; templates?: WorkflowDataTemplate[]; functions?: WorkflowFunction[]; dynamicValues?: Array<{path:string;label:string}> }) {
  const [dragged, setDragged] = useState<number | null>(null);
  const update = (i: number, key: string, value: unknown) => onChange(actions.map((a, idx) => idx === i ? { ...a, config: { ...a.config, [key]: value } } : a));
  const add = (type: string) => { if (actions.length < 5) onChange([...actions, action(type)]); };
  const move = (from: number, to: number) => { if (from === to || from === null || to < 0 || to >= actions.length) return; const next = [...actions]; const [item] = next.splice(from, 1); next.splice(to, 0, item); onChange(next); };
  const allowed = ACTIONS.filter(([v]) => resourceType === "FILE" || !["favorite", "tag", "mark_final", "share", "generate_link"].includes(v));
  return <div className="space-y-2.5">
    {actions.map((a, i) => <div key={`${a.type}-${i}`} draggable onDragStart={() => setDragged(i)} onDragOver={(e) => e.preventDefault()} onDrop={() => { if (dragged !== null) move(dragged, i); setDragged(null); }} className="workflow-action-row rounded-xl border border-slate-200 bg-white p-3 transition hover:border-slate-300 hover:shadow-sm">
      <div className="flex items-center gap-2"><span className="cursor-grab text-slate-400">⋮⋮</span><span className="flex-1 text-[11px] font-semibold text-slate-800">{txt(ar, ACTIONS.find((x) => x[0] === a.type)?.[1] ?? a.type, ACTIONS.find((x) => x[0] === a.type)?.[2] ?? a.type)}</span><span className="text-[9px] text-slate-400">{i + 1}/5</span><div className="workflow-reorder-controls flex items-center gap-1"><button type="button" onClick={() => move(i,i-1)} className="rounded-md border border-slate-200 px-1.5 py-1 text-[9px] text-slate-500">↑</button><button type="button" onClick={() => move(i,i+1)} className="rounded-md border border-slate-200 px-1.5 py-1 text-[9px] text-slate-500">↓</button></div><button type="button" onClick={() => onChange(actions.filter((_, idx) => idx !== i))} className="rounded-md px-1 text-slate-400 hover:bg-red-50 hover:text-red-600">×</button></div>
      {a.type === "notify" && <div className="mt-2 grid gap-1.5"><input value={String(a.config.title ?? "")} onChange={(e) => update(i, "title", e.target.value)} placeholder={txt(ar,"Notification title","عنوان الإشعار")} className="w-full rounded-lg border border-slate-200 px-2.5 py-2 text-[10.5px]"/><DynamicValueButtons ar={ar} values={dynamicValues} onInsert={(v) => update(i, "title", `${String(a.config.title ?? "")}${v}`)}/><textarea value={String(a.config.message ?? "")} onChange={(e) => update(i, "message", e.target.value)} placeholder={txt(ar,"Message. Supports {{fieldId}} and {{file.name}}","الرسالة. تدعم {{fieldId}} و {{file.name}}")} rows={2} className="w-full resize-none rounded-lg border border-slate-200 px-2.5 py-2 text-[10.5px]"/><DynamicValueButtons ar={ar} values={dynamicValues} onInsert={(v) => update(i, "message", `${String(a.config.message ?? "")}${v}`)}/></div>}
      {["move", "copy"].includes(a.type) && <input value={String(a.config.destinationFolderId ?? "")} onChange={(e) => update(i, "destinationFolderId", e.target.value)} placeholder={txt(ar,"Destination folder ID","معرّف مجلد الوجهة")} className="mt-2 w-full rounded-lg border border-slate-200 px-2.5 py-2 text-[10.5px]" />}
      {a.type === "tag" && <input value={String(a.config.name ?? "")} onChange={(e) => update(i, "name", e.target.value)} placeholder={txt(ar,"Tag name","اسم الوسم")} className="mt-2 w-full rounded-lg border border-slate-200 px-2.5 py-2 text-[10.5px]" />}
      {a.type === "share" && <div className="mt-2 grid gap-1.5"><input value={Array.isArray(a.config.userIds) ? a.config.userIds.join(", ") : String(a.config.userIds ?? "")} onChange={(e) => update(i, "userIds", e.target.value.split(",").map((x) => x.trim()).filter(Boolean))} placeholder={txt(ar,"User IDs, comma separated","معرّفات المستخدمين مفصولة بفواصل")} className="w-full rounded-lg border border-slate-200 px-2.5 py-2 text-[10.5px]"/><select value={String(a.config.permission ?? "VIEW")} onChange={(e) => update(i, "permission", e.target.value)} className="w-full rounded-lg border border-slate-200 px-2.5 py-2 text-[10.5px]"><option value="VIEW">{txt(ar,"View","عرض")}</option><option value="COMMENT">{txt(ar,"Comment","تعليق")}</option><option value="EDIT">{txt(ar,"Edit","تعديل")}</option></select></div>}
      {a.type === "request_approval" && <div className="mt-2 grid gap-2 rounded-xl bg-slate-50 p-2.5">
        <div className="rounded-lg border border-slate-200 bg-white p-2"><div className="text-[9.5px] font-medium text-slate-600">{txt(ar,"Participants","المشاركون")}</div><div className="mt-2 grid gap-2"><select multiple value={Array.isArray(a.config.userIds) ? a.config.userIds.map(String) : []} onChange={(e) => update(i, "userIds", Array.from(e.target.selectedOptions).map((o) => o.value))} className="h-20 w-full rounded-lg border border-slate-200 px-2 py-2 text-[10px]">{participants.map((p) => <option key={p.id} value={p.id}>{p.name || p.email}</option>)}</select><select multiple value={Array.isArray(a.config.groupIds) ? a.config.groupIds.map(String) : []} onChange={(e) => update(i, "groupIds", Array.from(e.target.selectedOptions).map((o) => o.value))} className="h-16 w-full rounded-lg border border-slate-200 px-2 py-2 text-[10px]"><option disabled>{txt(ar,"Groups","المجموعات")}</option>{groups.map((g) => <option key={g.id} value={g.id}>{g.name}{g.memberCount ? ` · ${g.memberCount}` : ""}</option>)}</select><div className="flex flex-wrap gap-1">{["MEMBER","ADMIN","SUPER_ADMIN"].map((role) => <label key={role} className="rounded-md border border-slate-200 px-2 py-1 text-[8.5px] text-slate-500"><input type="checkbox" className="me-1 accent-[#1B66EA]" checked={Array.isArray(a.config.roles) && a.config.roles.map(String).includes(role)} onChange={(e) => { const old = Array.isArray(a.config.roles) ? a.config.roles.map(String) : []; update(i, "roles", e.target.checked ? [...new Set([...old, role])] : old.filter((x) => x !== role)); }} />{role}</label>)}</div></div></div>
        <div className="grid grid-cols-2 gap-2"><label className="text-[9.5px] font-medium text-slate-600">{txt(ar,"Approval policy","سياسة الموافقة")}<select value={String(a.config.approvalPolicy ?? "ANY")} onChange={(e) => update(i, "approvalPolicy", e.target.value)} className="mt-1 w-full rounded-lg border border-slate-200 bg-white px-2.5 py-2 text-[10px]"><option value="ANY">{txt(ar,"Any approver","أي موافق")}</option><option value="ALL">{txt(ar,"All approvers","جميع الموافقين")}</option></select></label><label className="text-[9.5px] font-medium text-slate-600">{txt(ar,"Priority","الأولوية")}<select value={String(a.config.priority ?? "NORMAL")} onChange={(e) => update(i, "priority", e.target.value)} className="mt-1 w-full rounded-lg border border-slate-200 bg-white px-2.5 py-2 text-[10px]"><option value="NORMAL">{txt(ar,"Normal","عادية")}</option><option value="HIGH">{txt(ar,"High","عالية")}</option></select></label></div>
        <div className="grid grid-cols-2 gap-2"><label className="text-[9.5px] font-medium text-slate-600">{txt(ar,"Due after (minutes)","الموعد بعد (دقيقة)")}<input type="number" min={1} value={String(a.config.dueInMinutes ?? "")} onChange={(e) => update(i, "dueInMinutes", e.target.value ? Number(e.target.value) : undefined)} placeholder="1440" className="mt-1 w-full rounded-lg border border-slate-200 bg-white px-2.5 py-2 text-[10px]" /></label><label className="text-[9.5px] font-medium text-slate-600">{txt(ar,"Reminder after (minutes)","التذكير بعد (دقيقة)")}<input type="number" min={1} value={String(a.config.reminderInMinutes ?? "")} onChange={(e) => update(i, "reminderInMinutes", e.target.value ? Number(e.target.value) : undefined)} placeholder="720" className="mt-1 w-full rounded-lg border border-slate-200 bg-white px-2.5 py-2 text-[10px]" /></label></div>
        <label className="text-[9.5px] font-medium text-slate-600">{txt(ar,"Approval title","عنوان الموافقة")}<input value={String(a.config.title ?? "")} onChange={(e) => update(i, "title", e.target.value)} placeholder={txt(ar,"Approval title","عنوان الموافقة")} className="mt-1 w-full rounded-lg border border-slate-200 bg-white px-2.5 py-2 text-[10px]" /><DynamicValueButtons ar={ar} onInsert={(v) => update(i, "title", `${String(a.config.title ?? "")}${v}`)} /></label>
      </div>}
      {a.type === "data_template" && <div className="mt-2 grid gap-1.5"><select value={String(a.config.templateId ?? "")} onChange={(e) => { const id=e.target.value; const found=templates.find(t=>t.id===id); update(i,"templateId",id||undefined); if(found){ update(i,"template",found.template); update(i,"templateVersionId",found.activeVersion?.id||undefined); } }} className="wf-input"><option value="">{txt(ar,"Choose saved data template…","اختر قالب بيانات محفوظاً…")}</option>{templates.filter(t=>t.status!=="ARCHIVED").map(t=><option key={t.id} value={t.id}>{t.name} · v{t.activeVersion?.version??1}</option>)}</select><textarea value={String(a.config.template ?? "")} onChange={(e) => update(i, "template", e.target.value)} placeholder={txt(ar,"Template. Supports {{file.name}} and {{fieldId}}","القالب. يدعم {{file.name}} و {{fieldId}}")} rows={3} className="w-full resize-none rounded-lg border border-slate-200 px-2.5 py-2 text-[10.5px]"/><DynamicValueButtons ar={ar} onInsert={(v) => update(i, "template", `${String(a.config.template ?? "")}${v}`)}/>{<input value={String(a.config.outputFieldId ?? "")} onChange={(e) => update(i, "outputFieldId", e.target.value || undefined)} placeholder={txt(ar,"Output workflow field ID (optional)","معرّف حقل الإخراج (اختياري)")} className="w-full rounded-lg border border-slate-200 px-2.5 py-2 text-[10.5px]"/>}</div>}
      {a.type === "custom_function" && <div className="mt-2 grid gap-1.5"><select value={String(a.config.functionId ?? "")} onChange={(e) => { const id=e.target.value; update(i,"functionId",id||undefined); const fn=functions.find(f=>f.id===id); update(i,"functionVersionId",fn?.activeVersionId||undefined); }} className="wf-input"><option value="">{txt(ar,"Choose safe function…","اختر دالة آمنة…")}</option>{functions.map(f=><option key={f.id} value={f.id}>{f.name} · v{f.activeVersion?.version??1}</option>)}</select>{!functions.length&&<div className="rounded-lg bg-amber-50 p-2 text-[9px] text-amber-700">{txt(ar,"No custom functions are available. Built-in functions remain supported below.","لا توجد دوال مخصصة. الدوال المدمجة ما زالت مدعومة أدناه.")}</div>}{!a.config.functionId && String(a.config.functionKey ?? "set_workflow_field") === "set_workflow_field" && <><input value={String(a.config.fieldId ?? "")} onChange={(e) => update(i, "fieldId", e.target.value)} placeholder={txt(ar,"Workflow field ID","معرّف حقل سير العمل")} className="w-full rounded-lg border border-slate-200 px-2.5 py-2 text-[10.5px]"/><input value={String(a.config.value ?? "")} onChange={(e) => update(i, "value", e.target.value)} placeholder={txt(ar,"Value or {{file.name}}","القيمة أو {{file.name}}") } className="w-full rounded-lg border border-slate-200 px-2.5 py-2 text-[10.5px]"/><DynamicValueButtons ar={ar} onInsert={(v) => update(i, "value", `${String(a.config.value ?? "")}${v}`)}/></>}</div>}
      {a.type === "generate_link" && <label className="mt-2 flex items-center gap-2 text-[10.5px] text-slate-600"><input type="checkbox" checked={a.config.canDownload !== false} onChange={(e) => update(i, "canDownload", e.target.checked)} className="accent-[#1B66EA]" />{txt(ar,"Allow download","السماح بالتنزيل")}</label>}
      {a.type === "create_folder" && <div className="mt-2 grid gap-1.5"><input value={String(a.config.name ?? "")} onChange={(e) => update(i, "name", e.target.value)} placeholder={txt(ar,"Folder name","اسم المجلد")} className="w-full rounded-lg border border-slate-200 px-2.5 py-2 text-[10.5px]"/><input value={String(a.config.parentFolderId ?? "")} onChange={(e) => update(i, "parentFolderId", e.target.value)} placeholder={txt(ar,"Parent folder ID (optional)","معرّف المجلد الأب (اختياري)")} className="w-full rounded-lg border border-slate-200 px-2.5 py-2 text-[10.5px]"/></div>}
      {a.type === "favorite" && resourceType === "FOLDER" && <p className="mt-2 text-[10px] text-amber-600">{txt(ar,"This action is only available for files.","هذا الإجراء متاح للملفات فقط.")}</p>}
    </div>)}
    <div className="mb-2 flex items-center justify-between"><span className="text-[9px] font-semibold text-slate-500">{txt(ar,"Actions run as part of this phase","الإجراءات تنفذ ضمن هذه المرحلة")}</span><WorkflowHelp compact title={txt(ar,"ما هو الإجراء؟","What is an action?")} description={txt(ar,"الإجراء ينفذ مهمة فعلية مثل الإشعار أو النسخ أو طلب الموافقة عند وصول الانتقال إلى هذه المرحلة.","An action performs a real operation such as notification, copy or approval when the transition reaches this phase.")} /></div><select value="" disabled={actions.length >= 5} onChange={(e) => { if (e.target.value) add(e.target.value); e.currentTarget.value = ""; }} className="w-full rounded-xl border border-dashed border-slate-300 bg-slate-50 px-3 py-2.5 text-[10.5px] font-medium text-slate-600 outline-none hover:border-[#1B66EA] hover:bg-[#F8FBFF]"><option value="">＋ {txt(ar,"Add instant action","إضافة إجراء فوري")} {actions.length >= 5 ? "(5)" : ""}</option>{allowed.map(([v, en, arLabel]) => <option key={v} value={v}>{txt(ar, en, arLabel)}</option>)}</select>
  </div>;
}

function ConditionBuilder({ condition, onChange, fields, ar }: { condition: unknown; onChange: (next: unknown) => void; fields: WorkflowField[]; ar: boolean }) {
  const normalize = (value: unknown): ConditionGroup => {
    if (value && typeof value === "object" && !Array.isArray(value)) { const c = value as any; if ((c.logic === "AND" || c.logic === "OR") && Array.isArray(c.rules)) return c; if (Array.isArray(c.all)) return { logic: "AND", rules: c.all }; if (Array.isArray(c.any)) return { logic: "OR", rules: c.any }; }
    if (typeof value === "string" && value !== "any") return { logic: "AND", rules: [{ field: "fileType", operator: "equals", value }] };
    return { logic: "AND", rules: [] };
  };
  const root = normalize(condition);
  const ruleFields = [["fileType", "File type", "نوع الملف"],["extension","Extension","الامتداد"],["nameContains","File name","اسم الملف"],["folderId","Folder ID","معرّف المجلد"], ...fields.map((f) => [f.id, f.name, f.name])];
  const renderGroup = (group: ConditionGroup, path: number[], depth = 0): ReactNode => {
    const setGroup = (next: ConditionGroup) => { if (!path.length) onChange(next); else { const clone = normalize(condition); let cursor: any = clone; for (const i of path.slice(0,-1)) cursor = cursor.rules[i]; cursor.rules[path[path.length-1]] = next; onChange(clone); } };
    const updateAt = (index: number, node: any) => setGroup({ ...group, rules: group.rules.map((r,i)=>i===index?node:r) });
    return <div className={`${depth ? "border-slate-200 bg-white" : "border-slate-200 bg-slate-50"} rounded-xl border p-2.5`}><div className="flex items-center justify-between gap-2"><span className="text-[9px] font-semibold text-slate-600">{depth ? txt(ar,"Nested group","مجموعة متداخلة") : txt(ar,"Condition group","مجموعة الشروط")}</span><select value={group.logic} onChange={(e)=>setGroup({...group,logic:e.target.value as "AND"|"OR"})} className="rounded-lg border border-slate-200 bg-white px-2 py-1.5 text-[9px]"><option value="AND">AND</option><option value="OR">OR</option></select></div><div className="mt-2 space-y-2">{group.rules.map((node,index)=>{ if (node && typeof node === "object" && "logic" in (node as any) && Array.isArray((node as any).rules)) return <div key={index} className="ps-2">{renderGroup(node as ConditionGroup,[...path,index],depth+1)}<button type="button" onClick={()=>setGroup({...group,rules:group.rules.filter((_,i)=>i!==index)})} className="mt-1 text-[8.5px] text-red-500">{txt(ar,"Remove group","حذف المجموعة")}</button></div>; const r=node as ConditionRule; return <div key={index} className="grid grid-cols-[1fr_1fr_1fr_auto] gap-1.5"><select value={r.field} onChange={(e)=>updateAt(index,{...r,field:e.target.value})} className="rounded-lg border border-slate-200 bg-white px-2 py-2 text-[9px]">{ruleFields.map((f)=><option key={f[0]} value={f[0]}>{txt(ar,f[1],f[2])}</option>)}</select><select value={r.operator} onChange={(e)=>updateAt(index,{...r,operator:e.target.value})} className="rounded-lg border border-slate-200 bg-white px-2 py-2 text-[9px]"><option value="equals">=</option><option value="not_equals">≠</option><option value="contains">contains</option><option value="starts_with">starts with</option><option value="ends_with">ends with</option><option value="greater_than">&gt;</option><option value="less_than">&lt;</option></select><input value={r.value} onChange={(e)=>updateAt(index,{...r,value:e.target.value})} className="rounded-lg border border-slate-200 bg-white px-2 py-2 text-[9px]" placeholder={txt(ar,"Value","القيمة")}/><button type="button" onClick={()=>setGroup({...group,rules:group.rules.filter((_,i)=>i!==index)})} className="rounded-lg px-2 text-red-500">×</button></div>})}</div><div className="mt-2 flex flex-wrap gap-1.5"><button type="button" onClick={()=>setGroup({...group,rules:[...group.rules,{field:"fileType",operator:"equals",value:"PDF"}]})} className="rounded-lg border border-dashed border-slate-300 bg-white px-2.5 py-1.5 text-[8.5px] text-slate-600">＋ {txt(ar,"Rule","شرط")}</button>{depth < 3 && <button type="button" onClick={()=>setGroup({...group,rules:[...group.rules,{logic:"OR",rules:[{field:"extension",operator:"equals",value:"pdf"}]}]})} className="rounded-lg border border-dashed border-[#1B66EA]/40 bg-white px-2.5 py-1.5 text-[8.5px] text-[#1B66EA]">＋ {txt(ar,"Group","مجموعة")}</button>}</div></div>;
  };
  return <div><div className="mb-1.5 text-[9.5px] font-medium text-slate-600">{txt(ar,"Condition","الشرط")}</div>{renderGroup(root,[])}<div className="mt-1.5 text-[8px] text-slate-400">{txt(ar,"Nested groups are evaluated recursively by the workflow engine.","تُقيّم المجموعات المتداخلة بشكل تكراري بواسطة محرك سير العمل.")}</div></div>;
}

function WorkflowCanvas({ states, transitions, positions, setPositions, selected, onSelect, onAddTransition, zoom, setZoom, ar }: { states: StateDraft[]; transitions: TransitionDraft[]; positions: Position[]; setPositions: (p: Position[]) => void; selected: string; onSelect: (v: string) => void; onAddTransition: (from?: number) => void; zoom: number; setZoom: (v: number) => void; ar: boolean }) {
  const canvasRef = useRef<HTMLDivElement>(null);
  const [drag, setDrag] = useState<{ index: number; dx: number; dy: number } | null>(null);
  useEffect(() => { if (!drag) return; const move = (e: PointerEvent) => { const el=canvasRef.current; const rect = el?.getBoundingClientRect(); if (!el || !rect) return; const edge=70; const speed=16; if(e.clientX<rect.left+edge) el.scrollLeft=Math.max(0,el.scrollLeft-speed); else if(e.clientX>rect.right-edge) el.scrollLeft+=speed; if(e.clientY<rect.top+edge) el.scrollTop=Math.max(0,el.scrollTop-speed); else if(e.clientY>rect.bottom-edge) el.scrollTop+=speed; const next = [...positions]; next[drag.index] = { x: Math.max(30, (e.clientX - rect.left - drag.dx) / zoom), y: Math.max(40, (e.clientY - rect.top - drag.dy) / zoom) }; setPositions(next); }; const up = () => setDrag(null); window.addEventListener("pointermove", move); window.addEventListener("pointerup", up); return () => { window.removeEventListener("pointermove", move); window.removeEventListener("pointerup", up); }; }, [drag, positions, setPositions, zoom]);
  const width = Math.max(1500, ...positions.map((p) => p.x + 300), 1500); const height = Math.max(900, ...positions.map((p) => p.y + 190), 900);
  const center = (i: number) => ({ x: (positions[i]?.x ?? 100) + 135, y: (positions[i]?.y ?? 100) + 55 });
  return <div ref={canvasRef} className="relative h-full min-h-0 overflow-auto bg-[#F8FAFC]" dir="ltr">
    <div className="pointer-events-none absolute inset-0 opacity-60" style={{ backgroundImage: "radial-gradient(#CBD5E1 1px, transparent 1px)", backgroundSize: `${18 * zoom}px ${18 * zoom}px` }} />
    <div className="sticky left-0 top-0 z-40 flex h-12 items-center justify-between border-b border-slate-200 bg-white/90 px-4 backdrop-blur" dir={ar ? "rtl" : "ltr"}>
      <div className="flex items-center gap-2"><span className="rounded-lg bg-[#EEF4FF] px-2.5 py-1.5 text-[10px] font-semibold text-[#1B66EA]">{txt(ar,"Visual workflow","التصميم المرئي")}</span><span className="text-[10px] text-slate-400">{txt(ar,"Drag states • select lines • use + to branch","حرّك الحالات • اختر الخطوط • استخدم + للتفرع")}</span></div>
      <div className="flex items-center gap-1 rounded-lg border border-slate-200 bg-white p-1 shadow-sm"><button type="button" onClick={() => setZoom(Math.max(.7, Number((zoom - .1).toFixed(2))))} className="h-7 w-7 rounded-md hover:bg-slate-50">−</button><span className="w-12 text-center text-[10px] font-medium text-slate-600">{Math.round(zoom * 100)}%</span><button type="button" onClick={() => setZoom(Math.min(1.35, Number((zoom + .1).toFixed(2))))} className="h-7 w-7 rounded-md hover:bg-slate-50">＋</button></div>
    </div>
    <div className="relative" style={{ width: width * zoom, height: height * zoom }}>
      <svg className="pointer-events-none absolute inset-0 z-10" width={width * zoom} height={height * zoom} viewBox={`0 0 ${width} ${height}`}>
        <defs><marker id="wf-arrow" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto"><path d="M0,0 L9,4.5 L0,9 z" fill="#94A3B8"/></marker><marker id="wf-arrow-active" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto"><path d="M0,0 L9,4.5 L0,9 z" fill={BLUE}/></marker></defs>
        {transitions.map((t, i) => { const a = center(t.from), b = center(t.to); const mx = (a.x + b.x) / 2; const active = selected === `transition-${i}`; const d = `M ${a.x} ${a.y} C ${mx} ${a.y}, ${mx} ${b.y}, ${b.x} ${b.y}`; return <g key={i}><path d={d} fill="none" stroke={active ? BLUE : "#94A3B8"} strokeWidth={active ? 2.7 : 1.8} markerEnd={`url(#${active ? "wf-arrow-active" : "wf-arrow"})`} /><foreignObject x={mx - 65} y={(a.y + b.y) / 2 - 14} width="130" height="28"><button type="button" onClick={() => onSelect(`transition-${i}`)} className={`pointer-events-auto mx-auto block max-w-[125px] truncate rounded-full border bg-white px-3 py-1 text-[9.5px] shadow-sm transition hover:-translate-y-0.5 ${active ? "border-[#1B66EA] text-[#1B66EA] shadow-[#1B66EA]/10" : "border-slate-200 text-slate-600"}`}>{t.name || txt(ar,"Transition","انتقال")}</button></foreignObject></g>; })}
      </svg>
      {states.map((s, i) => <div key={i} onPointerDown={(e) => { if ((e.target as HTMLElement).closest("button")) return; const rect = canvasRef.current?.getBoundingClientRect(); if (!rect) return; setDrag({ index: i, dx: (e.clientX - rect.left) / zoom - positions[i].x, dy: (e.clientY - rect.top) / zoom - positions[i].y }); }} style={{ left: positions[i].x * zoom, top: positions[i].y * zoom, transform: `scale(${zoom})`, transformOrigin: "top left" }} className="absolute z-20 w-[270px] select-none">
        <button type="button" onClick={() => onSelect(`state-${i}`)} className={`w-full rounded-2xl border bg-white p-4 text-start shadow-[0_8px_25px_rgba(15,23,42,.08)] transition hover:-translate-y-0.5 ${selected === `state-${i}` ? "border-[#1B66EA] ring-4 ring-[#1B66EA]/10" : "border-slate-200"}`} dir={ar ? "rtl" : "ltr"}>
          <div className="flex items-start gap-3"><span className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-xl text-[12px] font-semibold ${i === 0 ? "bg-[#EEF4FF] text-[#1B66EA]" : s.terminal ? "bg-emerald-50 text-emerald-700" : "bg-slate-100 text-slate-600"}`}>{i + 1}</span><span className="min-w-0 flex-1"><span className="block text-[9px] font-semibold uppercase tracking-[.16em] text-slate-400">{txt(ar,"State","حالة")}</span><span className="mt-1 block truncate text-[13px] font-semibold text-slate-900">{s.name || txt(ar,"Untitled state","حالة بلا اسم")}</span><span className="mt-1 block line-clamp-2 text-[10.5px] leading-4 text-slate-500">{s.description || txt(ar,"Add a description","أضف وصفاً")}</span></span>{s.terminal && <span className="rounded-full bg-emerald-50 px-2 py-1 text-[8px] font-bold text-emerald-700">{txt(ar,"FINAL","نهائي")}</span>}</div>
        </button>
        <button type="button" onClick={(e) => { e.stopPropagation(); onAddTransition(i); }} className="absolute -bottom-3 left-1/2 z-30 h-7 w-7 -translate-x-1/2 rounded-full border border-slate-200 bg-white text-[15px] text-slate-500 shadow-sm transition hover:scale-110 hover:border-[#1B66EA] hover:text-[#1B66EA]">＋</button>
      </div>)}
      <div className="absolute bottom-7 left-7 z-40 overflow-hidden rounded-xl border border-slate-200 bg-white/95 shadow-lg backdrop-blur" dir={ar ? "rtl" : "ltr"}><div className="border-b border-slate-100 px-3 py-2 text-[9px] font-semibold uppercase tracking-[.15em] text-slate-400">{txt(ar,"Mini map","خريطة مصغرة")}</div><div className="relative h-[105px] w-[190px] bg-slate-50"><div className="absolute inset-3 rounded border border-slate-200 bg-white">{states.map((s, i) => <span key={i} className={`absolute h-2.5 w-5 rounded-sm ${s.terminal ? "bg-emerald-400" : "bg-[#1B66EA]"}`} style={{ left: `${Math.min(86, (positions[i].x / width) * 100)}%`, top: `${Math.min(86, (positions[i].y / height) * 100)}%` }} />)}</div></div></div>
    </div>
  </div>;
}

export default function WorkflowBuilderPage() {
  const { locale } = useLocale(); const ar = locale === "ar"; const router = useRouter(); const params = useSearchParams(); const urlId = params.get("id");
  const [workflowId, setWorkflowId] = useState<string | null>(urlId); const [calendarConfig, setCalendarConfig] = useState({ timezone: "UTC", workingDays: [1,2,3,4,5], workStart: "09:00", workEnd: "17:00", holidays: [] as string[] }); const [step, setStep] = useState<1 | 2 | 3>(1); const [name, setName] = useState(params.get("name") || ""); const [description, setDescription] = useState(params.get("description") || ""); const [mode, setMode] = useState<"AUTOMATIC" | "MANUAL">(params.get("mode") === "MANUAL" ? "MANUAL" : "AUTOMATIC"); const [resourceType, setResourceType] = useState<"FILE" | "FOLDER">(params.get("resourceType") === "FOLDER" ? "FOLDER" : "FILE");
  const [triggers, setTriggers] = useState<string[]>(["upload"]); const [fields, setFields] = useState<WorkflowField[]>([]); const [states, setStates] = useState<StateDraft[]>([{ name: "Start", description: "Workflow entry point", terminal: false }, { name: "Completed", description: "", terminal: true }]); const [transitions, setTransitions] = useState<TransitionDraft[]>([transitionDefaults(0, 1, 1)]); const [positions, setPositionsState] = useState<Position[]>(DEFAULT_POSITIONS.slice(0, 2));
  const [selected, setSelected] = useState("state-0"); const [phase, setPhase] = useState<Phase>("during"); const [zoom, setZoom] = useState(1); const [busy, setBusy] = useState(false); const [loading, setLoading] = useState(Boolean(urlId)); const [error, setError] = useState(""); const [message, setMessage] = useState(""); const [fieldDraft, setFieldDraft] = useState<WorkflowField | null>(null); const [dragFieldType, setDragFieldType] = useState<string | null>(null); const [fieldPointerDrag, setFieldPointerDrag] = useState<{ type: string; x: number; y: number } | null>(null); const fieldsDropRef = useRef<HTMLDivElement>(null); const [activationOpen, setActivationOpen] = useState(false); const [participants, setParticipants] = useState<WorkflowParticipant[]>([]); const [dataTemplates, setDataTemplates] = useState<WorkflowDataTemplate[]>([]); const [functions, setFunctions] = useState<WorkflowFunction[]>([]); const [dynamicValues, setDynamicValues] = useState<Array<{path:string;label:string}>>([]); const [groups, setGroups] = useState<GroupOption[]>([]); const [versionInfo, setVersionInfo] = useState<Array<{id:string;version:number;createdAt:string;publishedAt?:string|null}>>([]); const [fieldsDragOver, setFieldsDragOver] = useState(false); const [draggedFieldId, setDraggedFieldId] = useState<string | null>(null); const [mobileInspectorOpen, setMobileInspectorOpen] = useState(true);
  const setPositions = (next: Position[]) => { setPositionsState(next); if (workflowId && typeof window !== "undefined") localStorage.setItem(`workflow-layout:${workflowId}`, JSON.stringify(next)); };
  useEffect(() => {
    if (!fieldPointerDrag) return;
    const move = (e: PointerEvent) => { e.preventDefault(); const rect = fieldsDropRef.current?.getBoundingClientRect(); if (!rect) return; const edge=72; if(e.clientY<edge) window.scrollBy({top:-18,behavior:"auto"}); else if(e.clientY>window.innerHeight-edge) window.scrollBy({top:18,behavior:"auto"}); const inside = e.clientX >= rect.left && e.clientX <= rect.right && e.clientY >= rect.top && e.clientY <= rect.bottom; setFieldsDragOver(inside); setFieldPointerDrag((old) => old ? { ...old, x: e.clientX, y: e.clientY } : old); };
    const up = (e: PointerEvent) => { const rect = fieldsDropRef.current?.getBoundingClientRect(); const inside = !!rect && e.clientX >= rect.left && e.clientX <= rect.right && e.clientY >= rect.top && e.clientY <= rect.bottom; if (inside) { const type = fieldPointerDrag.type; setFieldDraft({ id: `${type}_${Date.now().toString(36)}`, name: "", description: "", type, required: false }); } setFieldPointerDrag(null); setFieldsDragOver(false); };
    window.addEventListener("pointermove", move, { passive: false }); window.addEventListener("pointerup", up); return () => { window.removeEventListener("pointermove", move); window.removeEventListener("pointerup", up); };
  }, [fieldPointerDrag]);

  useEffect(() => { void listWorkflowParticipants().then((items) => setParticipants(items.map((x) => x.user))).catch(() => setParticipants([])); void listWorkflowTemplates().then(setDataTemplates).catch(() => setDataTemplates([])); void listWorkflowFunctions().then((r) => setFunctions(r.custom ?? [])).catch(() => setFunctions([])); }, []);
  useEffect(() => { if (urlId) void listWorkflowVersions(urlId).then(setVersionInfo).catch(() => undefined); }, [urlId]);
  useEffect(() => { if (!urlId) return; void getWorkflow(urlId).then((w: Workflow) => { setWorkflowId(w.id); setName(w.name); setDescription(w.description || ""); setMode(w.mode); setResourceType(w.resourceType); if (w.calendarConfig && typeof w.calendarConfig === "object") setCalendarConfig({ timezone: String((w.calendarConfig as any).timezone ?? "UTC"), workingDays: Array.isArray((w.calendarConfig as any).workingDays) ? (w.calendarConfig as any).workingDays.map(Number) : [1,2,3,4,5], workStart: String((w.calendarConfig as any).workStart ?? "09:00"), workEnd: String((w.calendarConfig as any).workEnd ?? "17:00"), holidays: Array.isArray((w.calendarConfig as any).holidays) ? (w.calendarConfig as any).holidays.map(String) : [] }); const tv = w.steps.find((s) => s.kind === "TRIGGER")?.config.value; if (Array.isArray(tv)) setTriggers(tv.map(String)); else if (typeof tv === "string") setTriggers([tv]); const fv = w.steps.find((s) => s.kind === "WORKFLOW_FIELDS")?.config.value; if (Array.isArray(fv)) setFields(fv as WorkflowField[]); if (w.states.length) setStates(w.states.map((s) => ({ name: s.name, description: s.description || "", terminal: s.terminal }))); if (w.transitions.length) setTransitions(w.transitions.map((t) => { const p = normalizePhaseActions(t.actions); return { from: w.states.findIndex((s) => s.id === t.fromStateId), to: w.states.findIndex((s) => s.id === t.toStateId), name: t.name, description: t.description || "", trigger: t.trigger || "", condition: t.condition || "any", execution: t.trigger === "manual" ? "MANUAL" : "AUTOMATIC", ...p }; })); const saved = typeof window !== "undefined" ? localStorage.getItem(`workflow-layout:${w.id}`) : null; if (saved) { try { const parsed = JSON.parse(saved); if (Array.isArray(parsed)) setPositionsState(parsed); } catch {} } }).catch(() => setError(txt(ar,"Unable to load workflow.","تعذر تحميل سير العمل."))).finally(() => setLoading(false)); }, [urlId, ar]);
  useEffect(() => { setPositionsState((old) => states.map((_, i) => old[i] || DEFAULT_POSITIONS[i % DEFAULT_POSITIONS.length] || { x: 100 + (i % 3) * 360, y: 100 + Math.floor(i / 3) * 250 })); }, [states.length]);
  useEffect(() => { if (!urlId && mode === "MANUAL") setTransitions((v) => v.map((t, i) => i === 0 ? { ...t, execution: "MANUAL" } : t)); }, [mode, urlId]);

  const selectedStateIndex = selected.startsWith("state-") ? Number(selected.split("-")[1]) : -1; const selectedTransitionIndex = selected.startsWith("transition-") ? Number(selected.split("-")[1]) : -1; const selectedTransition = selectedTransitionIndex >= 0 ? transitions[selectedTransitionIndex] : null;
  const updateTransition = (i: number, patch: Partial<TransitionDraft>) => setTransitions((v) => v.map((t, idx) => idx === i ? { ...t, ...patch } : t));
  const addState = () => { if (states.length >= 20) return; const next = [...states, { name: `${txt(ar,"State","حالة")} ${states.length + 1}`, description: "", terminal: false }]; setStates(next); setPositions([...positions, DEFAULT_POSITIONS[states.length % DEFAULT_POSITIONS.length] || { x: 100, y: 100 }]); setSelected(`state-${next.length - 1}`); };
  const removeState = (i: number) => { if (states.length <= 1 || i === 0) return; const ns = states.filter((_, idx) => idx !== i); const nt = transitions.filter((t) => t.from !== i && t.to !== i).map((t) => ({ ...t, from: t.from > i ? t.from - 1 : t.from, to: t.to > i ? t.to - 1 : t.to })); setStates(ns); setTransitions(nt); setPositions(positions.filter((_, idx) => idx !== i)); setSelected("state-0"); };
  const addTransitionFrom = (from = Math.max(0, states.length - 2)) => { if (states.length < 2) { setError(txt(ar,"Add at least two states first.","أضف حالتين على الأقل أولاً.")); return; } const candidates = states.map((_, i) => i).filter((i) => i !== from); const to = candidates[0] ?? 0; const next = [...transitions, transitionDefaults(from, to, transitions.length + 1)]; setTransitions(next); setSelected(`transition-${next.length - 1}`); setError(""); };
  const saveField = () => { if (!fieldDraft?.name.trim()) return; setFields((v) => fieldDraft.id && v.some((f) => f.id === fieldDraft.id) ? v.map((f) => f.id === fieldDraft.id ? { ...fieldDraft, name: fieldDraft.name.trim() } : f) : [...v, { ...fieldDraft, name: fieldDraft.name.trim() }]); setFieldDraft(null); };
  const startFieldDrag = (type: string) => setDragFieldType(type);
  const onDropField = (e: DragEvent<HTMLDivElement>) => { e.preventDefault(); const type = e.dataTransfer.getData("application/x-workflow-field") || dragFieldType; if (!type) return; const base = { id: `${type}_${Date.now().toString(36)}`, name: "", description: "", type, required: false }; setFieldDraft(base); setDragFieldType(null); setFieldsDragOver(false); };
  const removeField = (id: string) => setFields((v) => v.filter((f) => f.id !== id));
  const moveField = (id: string, delta: number) => setFields((v) => { const index = v.findIndex((f) => f.id === id); const target = index + delta; if (index < 0 || target < 0 || target >= v.length) return v; const next = [...v]; const [item] = next.splice(index, 1); next.splice(target, 0, item); return next; });

  const validation = useMemo(() => { const issues: string[] = []; if (!name.trim()) issues.push(txt(ar,"Workflow name is required.","اسم سير العمل مطلوب.")); if (!states.length) issues.push(txt(ar,"Add at least one state.","أضف حالة واحدة على الأقل.")); if (!states.some((s) => s.terminal)) issues.push(txt(ar,"Add at least one final state.","أضف حالة نهائية واحدة على الأقل.")); if (mode === "AUTOMATIC" && !triggers.length) issues.push(txt(ar,"Select at least one starting trigger.","اختر محفز بداية واحداً على الأقل.")); transitions.forEach((t, i) => { if (t.from === t.to) issues.push(txt(ar,`Transition ${i + 1} cannot point to itself.`,`الانتقال ${i + 1} لا يمكن أن يشير إلى الحالة نفسها.`)); if (!t.name.trim()) issues.push(txt(ar,`Transition ${i + 1} needs a name.`,`الانتقال ${i + 1} يحتاج اسماً.`)); }); return issues; }, [name, states, transitions, mode, triggers, ar]);
  const buildPayload = (status: "DRAFT" | "ACTIVE") => ({ name: name.trim(), description: description.trim(), mode, resourceType, trigger: mode === "MANUAL" ? "manual" : triggers, condition: "any", actions: [], status, fields, calendarConfig, states, transitions: transitions.map((t) => ({ from: t.from, to: t.to, name: t.name.trim(), description: t.description, trigger: t.execution === "MANUAL" ? "manual" : t.trigger || undefined, condition: t.condition, actions: { before: t.before, during: t.during, after: t.after } })) });
  const save = async (status: "DRAFT" | "ACTIVE") => { if (busy) return; setError(""); setMessage(""); if (validation.length && status === "ACTIVE") { setError(validation[0]); setStep(3); return; } if (!name.trim()) { setError(txt(ar,"Workflow name is required.","اسم سير العمل مطلوب.")); setStep(1); return; } setBusy(true); try { const saved = workflowId ? await updateWorkflow(workflowId, buildPayload(status)) : await createWorkflow(buildPayload(status)); setWorkflowId(saved.id); setMessage(status === "ACTIVE" ? txt(ar,"Workflow activated successfully.","تم تفعيل سير العمل بنجاح.") : txt(ar,"Draft saved successfully.","تم حفظ المسودة بنجاح.")); if (status === "ACTIVE") window.setTimeout(() => router.push("/files/workflows"), 700); } catch (e) { setError(e instanceof Error ? e.message : txt(ar,"Something went wrong.","حدث خطأ غير متوقع.")); } finally { setBusy(false); } };
  const exportSpec = () => { const blob = new Blob([JSON.stringify(buildPayload("DRAFT"), null, 2)], { type: "application/json" }); const a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = `${name || "workflow"}.json`; a.click(); URL.revokeObjectURL(a.href); };
  const importSpec = async (file: File) => { try { const spec = JSON.parse(await file.text()) as Record<string, unknown>; setName(String(spec.name ?? "Imported workflow")); setDescription(String(spec.description ?? "")); setMode(spec.mode === "MANUAL" ? "MANUAL" : "AUTOMATIC"); setResourceType(spec.resourceType === "FOLDER" ? "FOLDER" : "FILE"); if (Array.isArray(spec.trigger)) setTriggers(spec.trigger.map(String)); if (Array.isArray(spec.fields)) setFields(spec.fields as WorkflowField[]); if (Array.isArray(spec.states)) setStates(spec.states as StateDraft[]); if (Array.isArray(spec.transitions)) setTransitions((spec.transitions as Record<string, unknown>[]).map((t, i) => { const p = normalizePhaseActions(t.actions); return { from: Number(t.from ?? 0), to: Number(t.to ?? 1), name: String(t.name ?? `Transition ${i + 1}`), description: String(t.description ?? ""), trigger: String(t.trigger ?? ""), condition: t.condition ?? "any", execution: t.trigger === "manual" ? "MANUAL" : "AUTOMATIC", ...p }; })); setMessage(txt(ar,"Workflow JSON imported as draft.","تم استيراد JSON كسير عمل مسودة.")); } catch { setError(txt(ar,"Invalid workflow JSON file.","ملف JSON لسير العمل غير صالح.")); } };

  if (loading) return <div className="flex h-full items-center justify-center bg-[#F7F9FC] text-[12px] text-slate-500">{txt(ar,"Loading workflow…","جارٍ تحميل سير العمل…")}</div>;
  return <div className="flex h-full min-h-0 flex-col bg-[#F7F9FC]" dir={ar ? "rtl" : "ltr"}>
    <header className="workflow-builder-header shrink-0 border-b border-slate-200 bg-white px-5 py-3 shadow-[0_1px_2px_rgba(15,23,42,.04)]"><div className="flex items-center justify-between gap-3"><div className="flex min-w-0 items-center gap-3"><Link href="/files/workflows" className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl border border-slate-200 text-slate-500 hover:bg-slate-50">←</Link><div className="min-w-0"><div className="text-[9px] font-semibold uppercase tracking-[.17em] text-[#1B66EA]">{txt(ar,"Workflow builder","منشئ سير العمل")}</div><div className="truncate text-[15px] font-semibold text-slate-900">{name || txt(ar,"Create workflow","إنشاء سير عمل")} <span className="ms-1 rounded-full bg-slate-100 px-2 py-1 text-[9px] font-medium text-slate-500">{mode === "MANUAL" ? txt(ar,"Manual","يدوي") : txt(ar,"Automatic","تلقائي")}</span>{versionInfo.length > 0 && <span className="ms-1 rounded-full bg-[#EEF4FF] px-2 py-1 text-[9px] font-medium text-[#1B66EA]">v{versionInfo[0].version}</span>}</div></div></div><div className="flex items-center gap-1.5"><WorkflowHelp compact title={txt(ar,"مساعدة هذه الواجهة","Help for this interface")} description={txt(ar,"تعرف على وظيفة الجزء الحالي قبل تعديله.","Understand the current area before changing it.")} tips={[txt(ar,"احفظ المسودة أثناء الإعداد، ولا تفعّلها حتى تتأكد من الحالات والانتقالات.","Save a draft while configuring, and activate only after checking states and transitions.")]}/><label className="cursor-pointer rounded-xl border border-slate-200 px-3 py-2 text-[10px] text-slate-600 hover:bg-slate-50">{txt(ar,"Import JSON","استيراد JSON")}<input type="file" accept="application/json" className="hidden" onChange={(e) => { const f = e.target.files?.[0]; if (f) void importSpec(f); e.currentTarget.value = ""; }} /></label><button type="button" onClick={exportSpec} className="rounded-xl border border-slate-200 px-3 py-2 text-[10px] text-slate-600 hover:bg-slate-50">{txt(ar,"Export JSON","تصدير JSON")}</button><button type="button" disabled={busy} onClick={() => void save("DRAFT")} className="rounded-xl border border-slate-200 px-3 py-2 text-[10px] font-medium text-slate-700">{txt(ar,"Save draft","حفظ المسودة")}</button><button type="button" disabled={busy} onClick={() => setActivationOpen(true)} className="wf-primary-button">{txt(ar,"Activate","تفعيل")}</button></div></div>
      <div className="workflow-stepper-wrap mt-3 flex items-center justify-center"><div className="workflow-stepper flex items-center gap-1 rounded-2xl bg-slate-100 p-1">{([[1,"Configure fields"],[2,"Design workflow"],[3,"Review"]] as const).map(([n,en]) => <button key={n} type="button" onClick={() => setStep(n)} className={`rounded-xl px-4 py-2 text-[10.5px] font-medium transition ${step === n ? "bg-white text-[#1B66EA] shadow-sm" : "text-slate-500 hover:text-slate-800"}`}><b className="me-1.5">{n}</b>{txt(ar,en,n===1?"إعداد الحقول":n===2?"تصميم سير العمل":"المراجعة")}</button>)}</div></div>
    </header>
    {error && <div className="mx-5 mt-2 rounded-xl border border-red-200 bg-red-50 px-3 py-2 text-[10.5px] text-red-700">{error}</div>}{message && <div className="mx-5 mt-2 rounded-xl border border-emerald-200 bg-emerald-50 px-3 py-2 text-[10.5px] text-emerald-700">{message}</div>}

    <div className="mx-5 mt-3 rounded-2xl border border-slate-200 bg-white px-4 py-3 shadow-sm"><div className="flex flex-wrap items-center gap-3"><div className="text-[10.5px] font-semibold text-slate-700">{txt(ar,"Business calendar","تقويم العمل")}</div><select value={calendarConfig.timezone} onChange={(e)=>setCalendarConfig(v=>({...v,timezone:e.target.value}))} className="rounded-lg border border-slate-200 px-2 py-1.5 text-[9.5px]"><option>UTC</option><option>Asia/Gaza</option><option>Asia/Riyadh</option><option>Europe/Berlin</option></select><input type="time" value={calendarConfig.workStart} onChange={(e)=>setCalendarConfig(v=>({...v,workStart:e.target.value}))} className="rounded-lg border border-slate-200 px-2 py-1.5 text-[9.5px]"/><span className="text-[9px] text-slate-400">—</span><input type="time" value={calendarConfig.workEnd} onChange={(e)=>setCalendarConfig(v=>({...v,workEnd:e.target.value}))} className="rounded-lg border border-slate-200 px-2 py-1.5 text-[9.5px]"/><div className="flex gap-1">{[1,2,3,4,5,6,7].map(d=><button type="button" key={d} onClick={()=>setCalendarConfig(v=>({...v,workingDays:v.workingDays.includes(d)?v.workingDays.filter(x=>x!==d):[...v.workingDays,d].sort()}))} className={`h-7 w-7 rounded-md border text-[8px] ${calendarConfig.workingDays.includes(d)?"border-[#1B66EA] bg-[#EEF4FF] text-[#1B66EA]":"border-slate-200 text-slate-400"}`}>{d}</button>)}</div><span className="text-[8.5px] text-slate-400">{txt(ar,"SLA timers use business days/hours","تستخدم مؤقتات SLA أيام وساعات العمل")}</span></div></div>
    {step === 1 && <div className="workflow-fields-step min-h-0 flex-1 overflow-hidden p-4"><div className="workflow-fields-layout grid h-full min-h-0 grid-cols-[260px_minmax(0,1fr)] gap-4">
      <aside className="workflow-fields-palette min-h-0 overflow-y-auto rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><div className="mb-4"><h2 className="text-[13px] font-semibold text-slate-900">{txt(ar,"Field types","أنواع الحقول")}</h2><p className="mt-1 text-[10.5px] leading-5 text-slate-500">{txt(ar,"Drag a field into the workspace. A configuration window opens only after you drop it.","اسحب الحقل إلى مساحة العمل. تظهر نافذة الإعداد بعد الإفلات فقط.")}</p></div><div className="space-y-2">{FIELD_TYPES.map(([v,en,arLabel,icon]) => <div key={v} draggable onDragStart={(e) => { e.dataTransfer.setData("application/x-workflow-field", v); e.dataTransfer.effectAllowed = "copy"; startFieldDrag(v); }} onDragEnd={() => setDragFieldType(null)} onPointerDown={(e) => { if (e.pointerType !== "mouse") { e.preventDefault(); setFieldPointerDrag({ type: v, x: e.clientX, y: e.clientY }); setFieldsDragOver(false); } }} className="group flex cursor-grab items-center gap-3 rounded-xl border border-dashed border-slate-300 bg-white px-3 py-3 transition duration-200 hover:-translate-y-0.5 hover:border-[#1B66EA] hover:bg-[#F8FBFF] hover:shadow-sm active:cursor-grabbing"><span className="flex h-8 w-8 items-center justify-center rounded-lg bg-slate-100 text-[10px] font-semibold text-slate-500 transition group-hover:bg-[#EEF4FF] group-hover:text-[#1B66EA]">{icon}</span><span className="min-w-0 flex-1 text-[10.5px] font-medium text-slate-700">{txt(ar,en,arLabel)}</span><span className="text-[12px] text-slate-300 group-hover:text-[#1B66EA]">↗</span></div>)}</div></aside>
      <section className="workflow-fields-workspace wf-card min-h-0 overflow-y-auto"><div className="border-b border-slate-100 px-6 py-5"><div className="flex items-start justify-between gap-4"><div><div className="flex items-start gap-2"><div><h2 className="text-[17px] font-semibold text-slate-900">{txt(ar,"Workflow fields","حقول سير العمل")}</h2><p className="mt-1 max-w-[720px] text-[11px] leading-5 text-slate-500">{txt(ar,"Collect feedback, assignees, approvers and other values while a workflow transition is in progress.","اجمع الملاحظات والمكلفين والموافقين والقيم الأخرى أثناء تنفيذ انتقال في سير العمل.")}</p></div><WorkflowHelp compact /></div></div></div></div>
        <div className="grid gap-4 p-6 lg:grid-cols-[1fr_310px]">
          <div ref={fieldsDropRef} onDragOver={(e) => { e.preventDefault(); setFieldsDragOver(true); }} onDragLeave={() => setFieldsDragOver(false)} onDrop={onDropField} className={`min-h-[430px] rounded-2xl border-2 border-dashed p-5 transition ${fieldsDragOver ? "border-[#1B66EA] bg-[#F8FBFF] scale-[1.005]" : "border-slate-200 bg-slate-50/50"}`}>
            {fields.length === 0 ? <div className="flex h-full min-h-[380px] flex-col items-center justify-center text-center"><div className={`flex h-16 w-16 items-center justify-center rounded-2xl transition ${fieldsDragOver ? "bg-[#EEF4FF] text-[#1B66EA] scale-110" : "bg-white text-slate-300 shadow-sm"}`}>＋</div><h3 className="mt-4 text-[13px] font-semibold text-slate-800">{fieldsDragOver ? txt(ar,"Release to configure the field","أفلت الحقل لبدء إعداده") : txt(ar,"Drop workflow fields here","أسقط حقول سير العمل هنا")}</h3><p className="mt-1 max-w-[360px] text-[10.5px] leading-5 text-slate-500">{txt(ar,"Choose a field type from the palette and drag it here. The editor appears after the drop.","اختر نوع الحقل من القائمة واسحبه إلى هنا. ستظهر نافذة الإعداد بعد الإفلات.")}</p></div> : <div className="space-y-3"><div className="flex items-center justify-between"><div className="text-[10px] font-semibold uppercase tracking-[.14em] text-slate-400">{fields.length} {txt(ar,"fields","حقول")}</div><span className="text-[10px] text-slate-400">{txt(ar,"Drop more fields anywhere in this area","يمكنك إفلات المزيد من الحقول في أي مكان هنا")}</span></div>{fields.map((f) => <div key={f.id} draggable onDragStart={() => setDraggedFieldId(f.id)} onDragOver={(e) => e.preventDefault()} onDrop={() => { if (draggedFieldId && draggedFieldId !== f.id) { setFields((v) => { const from = v.findIndex((x) => x.id === draggedFieldId); const to = v.findIndex((x) => x.id === f.id); if (from < 0 || to < 0) return v; const next = [...v]; const [item] = next.splice(from, 1); next.splice(to, 0, item); return next; }); } setDraggedFieldId(null); }} onDragEnd={() => setDraggedFieldId(null)} className={`group flex items-center gap-3 rounded-xl border bg-white p-3.5 transition hover:-translate-y-0.5 hover:shadow-sm ${draggedFieldId === f.id ? "border-[#1B66EA] opacity-60" : "border-slate-200"}`}><span className="cursor-grab touch-none text-slate-300">⋮⋮</span><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-slate-100 text-[10px] text-slate-600">{FIELD_TYPES.find((x) => x[0] === f.type)?.[3] ?? "□"}</span><div className="min-w-0 flex-1"><div className="truncate text-[12px] font-semibold text-slate-900">{f.name}</div><div className="mt-0.5 truncate text-[10px] text-slate-500">{txt(ar,FIELD_TYPES.find((x) => x[0] === f.type)?.[1] ?? f.type,FIELD_TYPES.find((x) => x[0] === f.type)?.[2] ?? f.type)}{f.required ? ` · ${txt(ar,"Mandatory","إلزامي")}` : ""}{f.description ? ` · ${f.description}` : ""}</div></div><div className="workflow-reorder-controls flex items-center gap-1"><button type="button" aria-label={ar ? "تحريك لأعلى" : "Move up"} onClick={() => moveField(f.id,-1)} className="rounded-md border border-slate-200 px-2 py-1 text-[10px] text-slate-500 hover:bg-slate-50">↑</button><button type="button" aria-label={ar ? "تحريك لأسفل" : "Move down"} onClick={() => moveField(f.id,1)} className="rounded-md border border-slate-200 px-2 py-1 text-[10px] text-slate-500 hover:bg-slate-50">↓</button></div><button type="button" onClick={() => setFieldDraft(f)} className="rounded-lg border border-slate-200 px-2.5 py-1.5 text-[10px] opacity-70 transition group-hover:opacity-100 hover:bg-slate-50">{txt(ar,"Edit","تعديل")}</button><button type="button" onClick={() => removeField(f.id)} className="rounded-lg px-2 py-1.5 text-[10px] text-red-500 opacity-70 transition group-hover:opacity-100 hover:bg-red-50">{txt(ar,"Delete","حذف")}</button></div>)}</div>}
          </div>
          <div className="space-y-4"><div className="rounded-2xl border border-slate-200 bg-white p-4"><div className="text-[10px] font-semibold uppercase tracking-[.14em] text-slate-400">{txt(ar,"Workflow details","تفاصيل سير العمل")}</div><label className="mt-3 block text-[10.5px] font-medium text-slate-700">{txt(ar,"Name","الاسم")}<input value={name} onChange={(e) => setName(e.target.value)} placeholder={txt(ar,"e.g. Review uploaded documents","مثال: مراجعة المستندات المرفوعة")} className="mt-1.5 w-full rounded-xl border border-slate-200 px-3 py-2.5 text-[11px] outline-none focus:border-[#1B66EA]" /></label><label className="mt-3 block text-[10.5px] font-medium text-slate-700">{txt(ar,"Description","الوصف")}<textarea value={description} onChange={(e) => setDescription(e.target.value)} rows={3} className="mt-1.5 w-full resize-none rounded-xl border border-slate-200 px-3 py-2.5 text-[11px]" /></label></div>
            <div className="rounded-2xl border border-slate-200 bg-slate-50/70 p-4"><div className="text-[10px] font-semibold uppercase tracking-[.14em] text-slate-400">{txt(ar,"Start mode","طريقة البدء")}</div><div className="mt-2 grid grid-cols-2 gap-2"><button type="button" onClick={() => setMode("AUTOMATIC")} className={`rounded-xl border px-3 py-2.5 text-[10.5px] font-medium ${mode === "AUTOMATIC" ? "border-[#1B66EA] bg-[#EEF4FF] text-[#1B66EA]" : "border-slate-200 bg-white text-slate-600"}`}>{txt(ar,"Automatic","تلقائي")}</button><button type="button" onClick={() => setMode("MANUAL")} className={`rounded-xl border px-3 py-2.5 text-[10.5px] font-medium ${mode === "MANUAL" ? "border-[#1B66EA] bg-[#EEF4FF] text-[#1B66EA]" : "border-slate-200 bg-white text-slate-600"}`}>{txt(ar,"Manual","يدوي")}</button></div><div className="mt-2 grid grid-cols-2 gap-2"><button type="button" onClick={() => setResourceType("FILE")} className={`rounded-xl border px-3 py-2.5 text-[10.5px] font-medium ${resourceType === "FILE" ? "border-[#1B66EA] bg-white text-[#1B66EA]" : "border-slate-200 bg-white text-slate-600"}`}>{txt(ar,"File-based","يعتمد على الملفات")}</button><button type="button" onClick={() => setResourceType("FOLDER")} className={`rounded-xl border px-3 py-2.5 text-[10.5px] font-medium ${resourceType === "FOLDER" ? "border-[#1B66EA] bg-white text-[#1B66EA]" : "border-slate-200 bg-white text-slate-600"}`}>{txt(ar,"Folder-based","يعتمد على المجلدات")}</button></div></div>
          </div>
        </div>
      </section>
    </div><div className="mt-3 flex shrink-0 items-center justify-between rounded-2xl border border-slate-200 bg-white px-4 py-3 shadow-sm"><button type="button" onClick={() => router.push("/files/workflows")} className="rounded-xl border border-slate-200 px-4 py-2 text-[10.5px] text-slate-600 hover:bg-slate-50">{txt(ar,"Back","رجوع")}</button><button type="button" onClick={() => setStep(2)} className="rounded-xl bg-[#0B8F55] px-5 py-2 text-[10.5px] font-semibold text-white shadow-sm hover:bg-[#087847]">{txt(ar,"Continue to design","متابعة إلى التصميم")} →</button></div></div>}

    {fieldPointerDrag && <div className="workflow-touch-drag-ghost" style={{ left: fieldPointerDrag.x, top: fieldPointerDrag.y }} dir={ar ? "rtl" : "ltr"}>{txt(ar, FIELD_TYPES.find((x) => x[0] === fieldPointerDrag.type)?.[1] ?? "Field", FIELD_TYPES.find((x) => x[0] === fieldPointerDrag.type)?.[2] ?? "حقل")}</div>}

    {step === 2 && <div className="workflow-design-step min-h-0 flex-1 overflow-hidden p-3"><div className="workflow-design-shell wf-card flex h-full min-h-0 overflow-hidden"><div className="workflow-elements-pane hidden w-[210px] shrink-0 border-e border-slate-200 bg-white xl:flex xl:flex-col" dir={ar ? "rtl" : "ltr"}><div className="border-b border-slate-100 p-4"><div className="flex items-center justify-between"><div><div className="text-[12px] font-semibold text-slate-900">{txt(ar,"Elements","العناصر")}</div><div className="mt-0.5 text-[9.5px] text-slate-500">{txt(ar,"Build your state machine","ابنِ منطق الحالات")}</div></div><WorkflowHelp compact /></div></div><div className="space-y-2 overflow-y-auto p-3"><button type="button" onClick={() => setStep(1)} className="w-full rounded-xl border border-dashed border-slate-300 p-3 text-start hover:border-[#1B66EA] hover:bg-[#F8FBFF]"><div className="text-[10px] font-semibold text-slate-800">＋ {txt(ar,"Workflow fields","حقول سير العمل")}</div><div className="mt-1 text-[9px] leading-4 text-slate-500">{fields.length} {txt(ar,"configured","مُعدّة")}</div></button><button type="button" onClick={() => addState()} className="w-full rounded-xl border border-dashed border-slate-300 p-3 text-start hover:border-[#1B66EA] hover:bg-[#F8FBFF]"><div className="text-[10px] font-semibold text-slate-800">＋ {txt(ar,"State","حالة")}</div><div className="mt-1 text-[9px] text-slate-500">{states.length}/20</div></button><button type="button" onClick={() => addTransitionFrom()} className="w-full rounded-xl border border-dashed border-slate-300 p-3 text-start hover:border-[#1B66EA] hover:bg-[#F8FBFF]"><div className="text-[10px] font-semibold text-slate-800">＋ {txt(ar,"Transition","انتقال")}</div><div className="mt-1 text-[9px] text-slate-500">{transitions.length}</div></button><div className="rounded-xl bg-slate-50 p-3"><div className="text-[9px] font-semibold uppercase tracking-[.14em] text-slate-400">{txt(ar,"Starting trigger","محفز البداية")}</div><div className="mt-2 space-y-1.5">{mode === "MANUAL" ? <div className="rounded-lg bg-white px-2.5 py-2 text-[9.5px] text-slate-600">{txt(ar,"Manual start","بدء يدوي")}</div> : TRIGGERS.map(([v,en,arLabel]) => <label key={v} className="flex items-center gap-2 text-[9.5px] text-slate-600"><input type="checkbox" checked={triggers.includes(v)} onChange={(e) => setTriggers((old) => e.target.checked ? [...new Set([...old,v])] : old.filter((x) => x !== v))} className="accent-[#1B66EA]" />{txt(ar,en,arLabel)}</label>)}</div></div></div></div><div className="workflow-canvas-pane min-w-0 flex-1"><WorkflowCanvas states={states} transitions={transitions} positions={positions} setPositions={setPositions} selected={selected} onSelect={(value) => { setSelected(value); setMobileInspectorOpen(true); }} onAddTransition={addTransitionFrom} zoom={zoom} setZoom={setZoom} ar={ar} /></div><aside className="w-[350px] shrink-0 overflow-y-auto border-s border-slate-200 bg-white" dir={ar ? "rtl" : "ltr"}><div className="sticky top-0 z-20 flex items-center justify-between border-b border-slate-100 bg-white/95 px-5 py-4 backdrop-blur"><div><div className="text-[9px] font-semibold uppercase tracking-[.15em] text-slate-400">{selectedTransition ? txt(ar,"Transition","انتقال") : txt(ar,"State","حالة")}</div><div className="mt-1 text-[14px] font-semibold text-slate-900">{selectedTransition ? selectedTransition.name : states[selectedStateIndex]?.name}</div></div><WorkflowHelp compact /></div><div className="space-y-4 p-5">
      {selectedStateIndex >= 0 && <><label className="block text-[10.5px] font-medium text-slate-600">{txt(ar,"State name","اسم الحالة")}<input value={states[selectedStateIndex]?.name ?? ""} onChange={(e) => setStates((v) => v.map((s,i)=>i===selectedStateIndex?{...s,name:e.target.value}:s))} className="mt-1.5 w-full rounded-xl border border-slate-200 px-3 py-2.5 text-[11px]" /></label><label className="block text-[10.5px] font-medium text-slate-600">{txt(ar,"Description","الوصف")}<textarea value={states[selectedStateIndex]?.description ?? ""} onChange={(e) => setStates((v) => v.map((s,i)=>i===selectedStateIndex?{...s,description:e.target.value}:s))} rows={3} className="mt-1.5 w-full resize-none rounded-xl border border-slate-200 px-3 py-2.5 text-[11px]" /></label><label className="flex items-center gap-2 text-[10.5px] text-slate-600"><input type="checkbox" checked={states[selectedStateIndex]?.terminal ?? false} onChange={(e) => setStates((v) => v.map((s,i)=>i===selectedStateIndex?{...s,terminal:e.target.checked}:s))} className="accent-[#0B8F55]" />{txt(ar,"Final state","حالة نهائية")}</label>{selectedStateIndex > 0 && <button type="button" onClick={() => removeState(selectedStateIndex)} className="w-full rounded-xl border border-red-100 bg-red-50 px-3 py-2.5 text-[10px] font-medium text-red-600">{txt(ar,"Delete state","حذف الحالة")}</button>}</>}
      {selectedTransition && <><label className="block text-[10.5px] font-medium text-slate-600">{txt(ar,"Transition name","اسم الانتقال")}<input value={selectedTransition.name} onChange={(e) => updateTransition(selectedTransitionIndex,{name:e.target.value})} className="mt-1.5 w-full rounded-xl border border-slate-200 px-3 py-2.5 text-[11px]" /></label><label className="block text-[10.5px] font-medium text-slate-600">{txt(ar,"Description","الوصف")}<textarea value={selectedTransition.description} onChange={(e) => updateTransition(selectedTransitionIndex,{description:e.target.value})} rows={2} className="mt-1.5 w-full resize-none rounded-xl border border-slate-200 px-3 py-2.5 text-[11px]" /></label><div className="grid grid-cols-2 gap-2"><label className="text-[10px] font-medium text-slate-600">{txt(ar,"From","من")}<select value={selectedTransition.from} onChange={(e)=>updateTransition(selectedTransitionIndex,{from:Number(e.target.value)})} className="mt-1 w-full rounded-xl border border-slate-200 px-2.5 py-2 text-[10.5px]">{states.map((s,i)=><option key={i} value={i}>{s.name}</option>)}</select></label><label className="text-[10px] font-medium text-slate-600">{txt(ar,"To","إلى")}<select value={selectedTransition.to} onChange={(e)=>updateTransition(selectedTransitionIndex,{to:Number(e.target.value)})} className="mt-1 w-full rounded-xl border border-slate-200 px-2.5 py-2 text-[10.5px]">{states.map((s,i)=><option key={i} value={i}>{s.name}</option>)}</select></label></div><div className="rounded-xl border border-slate-200 bg-slate-50 p-3"><div className="text-[10px] font-semibold text-slate-700">{txt(ar,"Execution","التنفيذ")}</div><div className="mt-2 grid grid-cols-2 gap-1.5"><button type="button" onClick={()=>updateTransition(selectedTransitionIndex,{execution:"AUTOMATIC"})} className={`rounded-lg border px-2 py-2 text-[10px] ${selectedTransition.execution==="AUTOMATIC"?"border-[#1B66EA] bg-white text-[#1B66EA]":"border-slate-200 text-slate-600"}`}>{txt(ar,"Automatic","تلقائي")}</button><button type="button" onClick={()=>updateTransition(selectedTransitionIndex,{execution:"MANUAL"})} className={`rounded-lg border px-2 py-2 text-[10px] ${selectedTransition.execution==="MANUAL"?"border-[#1B66EA] bg-white text-[#1B66EA]":"border-slate-200 text-slate-600"}`}>{txt(ar,"Manual","يدوي")}</button></div></div><label className="block text-[10.5px] font-medium text-slate-600">{txt(ar,"Trigger","المحفز")}<select disabled={selectedTransition.execution==="MANUAL"} value={selectedTransition.trigger} onChange={(e)=>updateTransition(selectedTransitionIndex,{trigger:e.target.value})} className="mt-1.5 w-full rounded-xl border border-slate-200 px-3 py-2.5 text-[10.5px]"><option value="">{txt(ar,"Any matching event","أي حدث مطابق")}</option>{TRIGGERS.map(([v,en,arLabel])=><option key={v} value={v}>{txt(ar,en,arLabel)}</option>)}</select></label><ConditionBuilder condition={selectedTransition.condition} onChange={(next)=>updateTransition(selectedTransitionIndex,{condition:next})} fields={fields} ar={ar}/><div className="border-t border-slate-100 pt-4"><div className="flex rounded-xl bg-slate-100 p-1">{(["before","during","after"] as Phase[]).map((p)=><button type="button" key={p} onClick={()=>setPhase(p)} className={`flex-1 rounded-lg px-2 py-2 text-[10px] font-medium ${phase===p?"bg-white text-[#1B66EA] shadow-sm":"text-slate-500"}`}>{txt(ar,p,p==="before"?"قبل":p==="during"?"أثناء":"بعد")}</button>)}</div><p className="mt-2.5 text-[9.5px] leading-5 text-slate-500">{phase==="before"?txt(ar,"Runs before the resource changes state.","يُنفذ قبل تغيير حالة المورد."):phase==="during"?txt(ar,"Collect input or perform actions while the transition is active.","اجمع المدخلات أو نفذ الإجراءات أثناء الانتقال."):txt(ar,"Runs after the resource reaches the next state.","يُنفذ بعد وصول المورد إلى الحالة التالية.")}</p><div className="mt-3"><ActionEditor actions={selectedTransition[phase]} onChange={(next)=>updateTransition(selectedTransitionIndex,{[phase]:next} as Partial<TransitionDraft>)} resourceType={resourceType} ar={ar} participants={participants} groups={groups} templates={dataTemplates} functions={functions} dynamicValues={dynamicValues}/></div></div></>}
      {!selectedTransition && selectedStateIndex < 0 && <div className="rounded-xl bg-slate-50 p-4 text-[10.5px] text-slate-500">{txt(ar,"Select a state or transition on the canvas to configure it.","اختر حالة أو انتقالاً من اللوحة لتعديله.")}</div>}
    </div></aside></div><div className="mt-3 flex shrink-0 items-center justify-between rounded-2xl border border-slate-200 bg-white px-4 py-3 shadow-sm"><button type="button" onClick={() => setStep(1)} className="rounded-xl border border-slate-200 px-4 py-2 text-[10.5px] text-slate-600">{txt(ar,"Back","رجوع")}</button><button type="button" onClick={() => setStep(3)} className="rounded-xl bg-[#0B8F55] px-5 py-2 text-[10.5px] font-semibold text-white">{txt(ar,"Continue to review","متابعة إلى المراجعة")} →</button></div></div>}

    {step === 3 && <div className="min-h-0 flex-1 overflow-y-auto p-5" dir={ar ? "rtl" : "ltr"}><div className="mx-auto max-w-[1000px] rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><div className="flex items-start justify-between gap-4"><div><div className="text-[9px] font-semibold uppercase tracking-[.15em] text-[#1B66EA]">{txt(ar,"Final review","المراجعة النهائية")}</div><h2 className="mt-1 text-[20px] font-semibold text-slate-900">{txt(ar,"Review workflow","مراجعة سير العمل")}</h2><p className="mt-1 text-[11px] text-slate-500">{txt(ar,"Check the connections and configuration before activation.","تحقق من الاتصالات والإعدادات قبل التفعيل.")}</p></div><WorkflowHelp helpKey="workflow.builder"/></div><div className="mt-6 grid gap-3 md:grid-cols-3"><div className="rounded-xl border border-slate-200 p-4"><div className="text-[9px] uppercase tracking-[.14em] text-slate-400">{txt(ar,"Workflow","سير العمل")}</div><div className="mt-1 text-[13px] font-semibold">{name || txt(ar,"Untitled","بلا اسم")}</div><div className="mt-1 text-[10px] text-slate-500">{mode === "MANUAL" ? txt(ar,"Manual","يدوي") : txt(ar,"Automatic","تلقائي")} · {resourceType === "FILE" ? txt(ar,"File-based","ملفات") : txt(ar,"Folder-based","مجلدات")}</div></div><div className="rounded-xl border border-slate-200 p-4"><div className="text-[9px] uppercase tracking-[.14em] text-slate-400">{txt(ar,"Structure","البنية")}</div><div className="mt-1 text-[13px] font-semibold">{states.length} {txt(ar,"states","حالات")} · {transitions.length} {txt(ar,"transitions","انتقالات")}</div><div className="mt-1 text-[10px] text-slate-500">{fields.length} {txt(ar,"custom fields","حقول مخصصة")}</div></div><div className={`rounded-xl border p-4 ${validation.length ? "border-amber-200 bg-amber-50" : "border-emerald-200 bg-emerald-50"}`}><div className="text-[9px] uppercase tracking-[.14em] text-slate-500">{txt(ar,"Status","الحالة")}</div><div className="mt-1 text-[13px] font-semibold">{validation.length ? `${validation.length} ${txt(ar,"issues","مشكلات")}` : txt(ar,"Ready to activate","جاهز للتفعيل")}</div></div></div><div className="mt-5 rounded-xl border border-slate-200"><div className="border-b border-slate-100 px-4 py-3 text-[11px] font-semibold">{txt(ar,"Validation","التحقق")}</div>{validation.length ? <div className="divide-y divide-slate-100">{validation.map((x,i)=><div key={i} className="flex gap-2 px-4 py-3 text-[10.5px] text-amber-700"><span>!</span>{x}</div>)}</div> : <div className="flex items-center gap-2 px-4 py-5 text-[10.5px] text-emerald-700"><span className="flex h-6 w-6 items-center justify-center rounded-full bg-emerald-100">✓</span>{txt(ar,"All required checks passed. The workflow is ready for activation.","اجتازت جميع الفحوصات المطلوبة. سير العمل جاهز للتفعيل.")}</div>}</div>{versionInfo.length > 0 && <div className="mt-5 rounded-xl border border-slate-200 bg-white p-4"><div className="flex items-center justify-between"><div><div className="text-[10px] font-semibold text-slate-700">{txt(ar,"Published versions","الإصدارات المنشورة")}</div><div className="mt-0.5 text-[9px] text-slate-400">{txt(ar,"Each activation publishes an immutable snapshot.","كل عملية تفعيل تنشر نسخة ثابتة غير قابلة للتعديل.")}</div></div><span className="rounded-full bg-slate-100 px-2 py-1 text-[9px] text-slate-500">{versionInfo.length}</span></div><div className="mt-3 flex gap-2 overflow-x-auto">{versionInfo.slice(0,6).map((v)=><div key={v.id} className="min-w-[120px] rounded-lg border border-slate-200 bg-slate-50 p-2.5"><div className="text-[11px] font-semibold text-slate-800">v{v.version}</div><div className="mt-1 text-[8.5px] text-slate-400">{new Date(v.publishedAt ?? v.createdAt).toLocaleString(ar ? "ar" : "en")}</div></div>)}</div></div>}
      <div className="mt-5 rounded-xl bg-[#F7FAFF] p-4 text-[10.5px] leading-5 text-slate-600">{txt(ar,"Automatic workflows react to configured file/folder events. Manual workflows become available from the file actions menu and create a waiting task when a manual transition is reached.","تستجيب سير العمل التلقائية لأحداث الملفات والمجلدات المحددة. أما سير العمل اليدوية فتظهر ضمن قائمة إجراءات الملف وتنشئ مهمة انتظار عند الوصول إلى انتقال يدوي." )}</div><div className="mt-6 flex justify-between"><button type="button" onClick={() => setStep(2)} className="rounded-xl border border-slate-200 px-5 py-2.5 text-[10.5px]">{txt(ar,"Back to design","العودة إلى التصميم")}</button><button type="button" disabled={busy || validation.length > 0} onClick={() => setActivationOpen(true)} className="wf-primary-button px-6 disabled:opacity-40">{txt(ar,"Activate workflow","تفعيل سير العمل")}</button></div></div></div>}

    {fieldDraft && <FieldEditor draft={fieldDraft} ar={ar} onChange={setFieldDraft} onCancel={() => setFieldDraft(null)} onSave={saveField} />}
    {activationOpen && <div className="fixed inset-0 z-[240] flex items-center justify-center bg-slate-950/40 p-4"><div className="w-[min(560px,94vw)] rounded-2xl border border-slate-200 bg-white p-7 shadow-2xl" dir={ar ? "rtl" : "ltr"}><div className="flex items-start gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#EEF4FF] text-[#1B66EA]">✓</div><div><h2 className="text-[18px] font-semibold text-slate-900">{txt(ar,"Activate workflow?","تفعيل سير العمل؟")}</h2><p className="mt-2 text-[11px] leading-5 text-slate-600">{txt(ar,`You are about to activate “${name || "new workflow"}”.`,`أنت على وشك تفعيل «${name || "سير عمل جديد"}».`)}</p></div></div>{validation.length ? <div className="mt-4 rounded-xl border border-amber-200 bg-amber-50 p-3 text-[10.5px] text-amber-800">{validation[0]}</div> : null}<div className="mt-6 flex justify-end gap-2"><button type="button" onClick={() => setActivationOpen(false)} className="rounded-xl border border-slate-200 px-4 py-2 text-[10.5px]">{txt(ar,"Cancel","إلغاء")}</button><button type="button" disabled={busy || validation.length > 0} onClick={() => { setActivationOpen(false); void save("ACTIVE"); }} className="wf-primary-button px-5 disabled:opacity-40">{txt(ar,"Activate","تفعيل")}</button></div></div></div>}
  </div>;
}
